def latestTimeByReplacingZeroes(s: str) -> str:
    s_list = list(s)

    # Handle HH: First digit
    if s_list[0] == '?':
        # If the second digit is 0 or 1, the first can be 1.
        # If the second digit is 2-9, the first must be 0 to stay <= 11.
        # If the second digit is also '?', we can pick 1 for the first.
        if s_list[1] == '?' or s_list[1] <= '1':
            s_list[0] = '1'
        else:
            s_list[0] = '0'

    # Handle HH: Second digit
    if s_list[1] == '?':
        # If the first digit is 1, max is 1. If 0, max is 9.
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle MM: Third digit (tens place)
    if s_list[3] == '?':
        s_list[3] = '5'

    # Handle MM: Fourth digit (ones place)
    if s_list[4] == '?':
        s_list[4] = '9'

    return "".join(s_list)
