import sys

def rotate(shape):
    """Rotates a 4x4 grid 90 degrees clockwise."""
    new_shape = [['.' for _ in range(4)] for _ in range(4)]
    for r in range(4):
        for c in range(4):
            new_shape[c][3-r] = shape[r][c]
    return new_shape

def get_all_rotations(shape):
    """Returns a list of the 4 possible rotations of the 4x4 grid."""
    rots = []
    curr = shape
    for _ in range(4):
        rots.append(curr)
        curr = rotate(curr)
    return rots

def get_normalized_coords(shape):
    """Extracts coordinates of '#' and shifts them to start at (0, 0)."""
    coords = []
    for r in range(4):
        for c in range(4):
            if shape[r][c] == '#':
                coords.append((r, c))
    if not coords:
        return []
    min_r = min(r for r, c in coords)
    min_c = min(c for r, c in coords)
    return sorted([(r - min_r, c - min_c) for r, c in coords])

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    raw_grids = []
    for i in range(0, 12, 4):
        grid = [list(row) for row in input_data[i:i+4]]
        raw_grids.append(grid)

    # For each polyomino, generate all unique normalized shapes (rotations)
    poly_shapes = []
    for grid in raw_grids:
        unique_shapes = set()
        for rot in get_all_rotations(grid):
            coords = tuple(get_normalized_coords(rot))
            unique_shapes.add(coords)
        poly_shapes.append(list(unique_shapes))

    # Pre-calculate total number of # cells. Must be 16 for Yes.
    total_cells = sum(sum(row.count('#') for row in grid) for grid in raw_grids)
    if total_cells != 16:
        print("No")
        return

    grid_state = [[False for _ in range(4)] for _ in range(4)]

    def can_place(coords, dr, dc):
        for r, c in coords:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid_state[nr][nc]:
                return False
        return True

    def place(coords, dr, dc, val):
        for r, c in coords:
            grid_state[r + dr][c + dc] = val

    def backtrack(poly_idx):
        if poly_idx == 3:
            # Check if all cells are filled
            return all(all(row) for row in grid_state)

        for shape in poly_shapes[poly_idx]:
            # Try all possible top-left positions for the normalized shape
            for dr in range(4):
                for dc in range(4):
                    if can_place(shape, dr, dc):
                        place(shape, dr, dc, True)
                        if backtrack(poly_idx + 1):
                            return True
                        place(shape, dr, dc, False)
        return False

    if backtrack(0):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

