import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    MOD = 998244353

    # Initial green cells and red cells
    green_cells = []
    red_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                green_cells.append((r, c))
            else:
                red_cells.append((r, c))

    # Calculate current number of green connected components (C)
    visited = [[False for _ in range(W)] for _ in range(H)]
    current_components = 0
    for r, c in green_cells:
        if not visited[r][c]:
            current_components += 1
            stack = [(r, c)]
            visited[r][c] = True
            while stack:
                curr_r, curr_c = stack.pop()
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#' and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))

    # DSU to find which component each green cell belongs to
    parent = {}
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    for r, c in green_cells:
        parent[(r, c)] = (r, c)

    for r, c in green_cells:
        for dr, dc in [(0, 1), (1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                union((r, c), (nr, nc))

    # For each red cell, calculate the change in components if it turns green
    # New Components = Current Components + 1 - (number of distinct green components it connects)
    total_sum = 0
    for r, c in red_cells:
        neighboring_components = set()
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                neighboring_components.add(find((nr, nc)))

        components_after = current_components + 1 - len(neighboring_components)
        total_sum = (total_sum + components_after) % MOD

    # Expected Value = total_sum / count of red cells
    num_red = len(red_cells)
    # Modulo inverse using Fermat's Little Theorem
    inv_num_red = pow(num_red, MOD - 2, MOD)

    print((total_sum * inv_num_red) % MOD)

if __name__ == "__main__":
    # Increase recursion depth for deep DSU/DFS
    sys.setrecursionlimit(2000000)
    solve()
