import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Use a large value for infinity
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = w
        idx += 3

    # Floyd-Warshall to find shortest paths between all pairs
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # dp[mask][last_vertex] = min cost to visit all vertices in mask, ending at last_vertex
    # The mask represents the set of vertices visited at least once.
    dp = [[INF] * N for _ in range(1 << N)]

    # Initial states: start at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Bitmask DP
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to a vertex v that hasn't been visited (or even if it has, 
            # Floyd-Warshall shortest paths handle the "intermediate" visits)
            for v in range(N):
                if dist[u][v] == INF:
                    continue

                new_mask = mask | (1 << v)
                new_dist = dp[mask][u] + dist[u][v]
                if dp[new_mask][v] > new_dist:
                    dp[new_mask][v] = new_dist

    # The answer is the minimum value in dp[(1 << N) - 1]
    ans = min(dp[(1 << N) - 1])

    if ans == INF:
        print("No")
    else:
        print(int(ans))

if __name__ == "__main__":
    solve()

```

