def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first character that is NOT 'a'.
    # We want to start our transformation from the first character that can be reduced
    # to something smaller without wrapping around ('a' to 'z' is not smaller).
    start = -1
    for i in range(n):
        if s_list[i] != 'a':
            start = i
            break

    # If the string consists only of 'a's, we must still perform one operation.
    # The smallest change is to change the last 'a' to 'z'.
    if start == -1:
        s_list[-1] = 'z'
        return "".join(s_list)

    # From the start index, continue replacing characters until we encounter 'a'
    # or reach the end of the string.
    for i in range(start, n):
        if s_list[i] == 'a':
            break
        # Replace character with the previous character in the alphabet
        s_list[i] = chr(ord(s_list[i]) - 1)

    return "".join(s_list)
