def numberOfRightTriangles(grid):
    rows = len(grid)
    cols = len(grid[0])

    row_counts = [0] * rows
    col_counts = [0] * cols

    # Precompute the number of 1s in each row and each column
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                row_counts[r] += 1
                col_counts[c] += 1

    total_triangles = 0

    # A right triangle is formed by a vertex (r, c) that is 1, 
    # combined with any other 1 in the same row and any other 1 in the same column.
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Number of other 1s in the same row is (row_counts[r] - 1)
                # Number of other 1s in the same column is (col_counts[c] - 1)
                total_triangles += (row_counts[r] - 1) * (col_counts[c] - 1)

    return total_triangles
