def areaOfMaxDiagonalRectangle(dimensions):
    max_diag_sq = 0
    max_area = 0

    for length, width in dimensions:
        # We use diagonal squared (l^2 + w^2) to avoid floating point issues with sqrt
        diag_sq = length**2 + width**2
