def beautifulSubstrings(s: str, k: int) -> int:
    vowels_set = set('aeiou')
    n = len(s)
    count = 0

    # Since the constraints are small (s.length <= 1000), 
    # an O(n^2) solution is acceptable.
    for i in range(n):
        vowels = 0
        consonants = 0
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # A string is beautiful if:
            # 1. vowels == consonants
            # 2. (vowels * consonants) % k == 0
            if vowels == consonants:
                if (vowels * consonants) % k == 0:
                    count += 1

    return count
