import sys

def solve():
    # Use fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    T_prime = input_data[1]
    len_tp = len(T_prime)

    results = []

    for i in range(N):
        S = input_data[i + 2]
        len_s = len(S)

        # Case 1: S is T. T' is equal to T (T' == S).
        # Case 2: S is T. T' is obtained by inserting one char into S. (len(T') == len(S) + 1)
        # Case 3: S is T. T' is obtained by deleting one char from S. (len(T') == len(S) - 1)
        # Case 4: S is T. T' is obtained by changing one char in S. (len(T') == len(S))

        diff = len_tp - len_s

        if abs(diff) > 1:
            continue

        possible = False

        if diff == 0:
            # Either they are equal or one character differs
            mismatch = 0
            for char_tp, char_s in zip(T_prime, S):
                if char_tp != char_s:
                    mismatch += 1
                    if mismatch > 1:
                        break
            if mismatch <= 1:
                possible = True

        elif diff == 1:
            # T' is S + one inserted character
            # Check if S is a subsequence of T' with only one deletion
            it_s = 0
            it_tp = 0
            while it_s < len_s and it_tp < len_tp:
                if S[it_s] == T_prime[it_tp]:
                    it_s += 1
                it_tp += 1
            if it_s == len_s:
                possible = True

        elif diff == -1:
            # T' is S - one deleted character
            # Check if T' is a subsequence of S with only one deletion
            it_tp = 0
            it_s = 0
            while it_tp < len_tp and it_s < len_s:
                if T_prime[it_tp] == S[it_s]:
                    it_tp += 1
                it_s += 1
            if it_tp == len_tp:
                possible = True

        if possible:
            results.append(i + 1)

    print(len(results))
    print(*(results))

