def solve(n):
    if n < 4:
        return []

    # Sieve of Eratosthenes to find all primes up to n
    primes_bool = [True] * (n + 1)
    primes_bool[0] = primes_bool[1] = False
    for p in range(2, int(n**0.5) + 1):
        if primes_bool[p]:
            for i in range(p * p, n + 1, p):
                primes_bool[i] = False

    result = []
    # Iterate x from 2 up to n/2 to ensure x <= y and avoid duplicates
    for x in range(2, (n // 2) + 1):
        y = n - x
        if primes_bool[x] and primes_bool[y]:
            result.append([x, y])

    return result
