def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    # The median index according to the definition (larger of two for even length)
    # For length 5, index is 2. For length 6, index is 3.
    mid = n // 2

    operations = 0

    # The median must be k. If the current median is already k, ops = 0.
    # If current median < k, we must increase the median and all elements to its right that are < k.
    if nums[mid] < k:
        for i in range(mid, n):
            if nums[i] < k:
                operations += k - nums[i]
            else:
                # Since the array is sorted, once we hit an element >= k, 
                # no further elements to the right need increasing.
                break
    # If current median > k, we must decrease the median and all elements to its left that are > k.
    elif nums[mid] > k:
        for i in range(mid, -1, -1):
            if nums[i] > k:
                operations += nums[i] - k
            else:
                # Since the array is sorted, once we hit an element <= k,
                # no further elements to the left need decreasing.
                break

    return operations
