import sys
from collections import deque

def solve():
    # Increase recursion depth for deep DP/DFS if necessary
    sys.setrecursionlimit(2000)

    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # Points of interest: Start, Candies, Goal
    nodes = [start_pos] + candies + [goal_pos]
    num_nodes = len(nodes)
    num_candies = len(candies)

    # Precompute distances between all pairs of points of interest using BFS
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    for i in range(num_nodes):
        # BFS from nodes[i]
        sr, sc = nodes[i]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(num_nodes):
            tr, tc = nodes[j]
            if dists[tr][tc] != -1:
                dist_matrix[i][j] = dists[tr][tc]

    # DP state: dp[mask][i] is the min distance to visit candies in mask, ending at candy i
    # mask is a bitmask of visited candies (0 to num_candies-1)
    # nodes mapping: 0: Start, 1..num_candies: Candies, num_candies+1: Goal

    # dp[mask][i] where i is index of candy (0 to num_candies-1)
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Initialize from start
    for i in range(num_candies):
        d = dist_matrix[0][i + 1]
        if d <= T:
            dp[1 << i][i] = d

    # Fill DP
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue

            # Try moving to another candy j not in mask
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_dist = dp[mask][i] + dist_matrix[i + 1][j + 1]
                    if new_dist <= T:
                        new_mask = mask | (1 << j)
                        if new_dist < dp[new_mask][j]:
                            dp[new_mask][j] = new_dist

    # Calculate max candies possible to reach goal
    max_candies = -1

    # Check if direct start to goal is possible
    if dist_matrix[0][num_nodes - 1] <= T:
        max_candies = 0

    # Check combinations of candies
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] != float('inf'):
                # Total distance = dist to last candy + dist from last candy to goal
                total_dist = dp[mask][i] + dist_matrix[i + 1][num_nodes - 1]
                if total_dist <= T:
                    # count set bits in mask
                    count = bin(mask).count('1')
                    if count > max_candies:
                        max_candies = count

    print(max_candies)

if __name__ == "__main__":
    solve()
```

