def isGoodArray(nums):
    n = len(nums) - 1
    if n < 1:
        return False

    # The base[n] array has length n + 1.
    # It must contain elements 1 to n-1 once, and n twice.

    # Check if the length is consistent with the max element
    max_val = max(nums)
    if max_val != n:
        return False

    # Count occurrences of each number
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    # Check if 1 to n-1 appear exactly once
    for i in range(1, n):
        if counts.get(i) != 1:
            return False

    # Check if n appears exactly twice
    if counts.get(n) != 2:
        return False

    return True
