def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        # Base case: if we've processed the whole string and the target is 0, we found a partition
        if not s:
            return target == 0
        # If target becomes negative, this path is invalid
        if target < 0:
            return False

        # Try every possible split from the current position
        for i in range(1, len(s) + 1):
            substring = s[:i]
            val = int(substring)
            if can_partition(s[i:], target - val):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_punishment += i * i

    return total_punishment
