def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    res = ""

    # Sliding window / Two-pointer approach to find all beautiful substrings
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                current_substring = s[i : j + 1]
                current_len = j - i + 1

                if current_len < min_len:
                    min_len = current_len
                    res = current_substring
                elif current_len == min_len:
                    if current_substring < res:
                        res = current_substring
                # Once we reach k ones, expanding further will only increase length
                break
            elif ones_count > k:
                break

    return res
