import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid to track occupied cells
    grid = [[False for _ in range(W)] for _ in range(H)]
    used_tiles = [False] * N

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        # Base case: all cells covered
        if r == -1:
            return True

        # Try placing each available tile
        for i in range(N):
            if not used_tiles[i]:
                # Try both rotations
