    # Check horizontal sequences
    if W >= K:
        for i in range(H):
            row = S[i]
            # Use a sliding window to count 'x' and '.'
            current_x = 0
            current_dot = 0
            for j in range(W):
                # Add new element to window
                if row[j] == 'x':
                    current_x += 1
                elif row[j] == '.':
                    current_dot += 1

                # Remove element that falls out of window
                if j >= K:
                    if row[j-K] == 'x':
                        current_x -= 1
                    elif row[j-K] == '.':
                        current_dot -= 1

                # If window is size K and has no 'x', it's a candidate
                if j >= K - 1:
                    if current_x == 0:
                        if current_dot < min_ops:
                            min_ops = current_dot

    # Check vertical sequences
    if H >= K:
        for j in range(W):
            # Use a sliding window to count 'x' and '.' for the column
            current_x = 0
            current_dot = 0
            for i in range(H):
                char = S[i][j]
                if char == 'x':
                    current_x += 1
                elif char == '.':
                    current_dot += 1

                if i >= K:
                    prev_char = S[i-K][j]
                    if prev_char == 'x':
                        current_x -= 1
                    elif prev_char == '.':
                        current_dot -= 1

                if i >= K - 1:
