import math

def canVisitAllPairs(nums):
    if len(nums) == 1:
        return True

    # Disjoint Set Union (DSU) to manage connected components
    parent = list(range(len(nums)))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the index of the first number that has this factor
    prime_to_index = {}

    for i, val in enumerate(nums):
        if val == 1:
            return False  # 1 cannot have gcd > 1 with any other number

        # Standard prime factorization
        temp = val
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, len(nums)):
        if find(i) != root:
            return False

    return True
