def specialPermutations(nums):
    n = len(nums)
    MOD = 10**9 + 7

    # Precompute divisibility to speed up transitions
    # adj[i] contains indices j such that nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    adj[i].append(j)

    # dp[mask][last_idx] stores the number of permutations using elements in 'mask'
    # ending with the element at 'last_idx'
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: single elements
    for i in range(n):
        dp[1 << i][i] = 1

    # Fill DP table
    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue

            # Try adding a new element to the permutation
            for next_idx in adj[last]:
                if not (mask & (1 << next_idx)):
                    new_mask = mask | (1 << next_idx)
                    dp[new_mask][next_idx] = (dp[new_mask][next_idx] + dp[mask][last]) % MOD

    # Sum up all permutations that use all elements
    full_mask = (1 << n) - 1
    result = sum(dp[full_mask]) % MOD
    return result
